function validate([nums1, nums2]) {
  if (nums1.length !== nums2.length) return 'nums1 and nums2 must have the same length.';
  if (nums1.length < 1 || nums1.length > 20000) return 'The length n is between 1 and 20000.';
  if (nums1.length % 2 !== 0) return 'The length n must be even.';
  const bad = v => !Number.isInteger(v) || v < 1 || v > 1000000000;
  if (nums1.some(bad) || nums2.some(bad)) return 'Every value is an integer between 1 and 10^9.';
  return null;
}

