function maximumSetSize(nums1, nums2) {
  const half = nums1.length / 2;
  const set1 = new Set(nums1);
  const set2 = new Set(nums2);
  let common = 0;
  for (const value of set1) {
    if (set2.has(value)) {
      common++;
    }
  }
  const only1 = Math.min(set1.size - common, half);
  const only2 = Math.min(set2.size - common, half);
  const shared = Math.min(common, 2 * half - only1 - only2);
  return only1 + only2 + shared;
}

