function maximumSetSize(nums1, nums2) {
  const n = nums1.length;
  const keepSets = (nums) => {
    const result = [];
    for (let mask = 0; mask < (1 << n); mask++) {
      let bits = 0;
      for (let i = 0; i < n; i++) if (mask & (1 << i)) bits++;
      if (bits !== n / 2) continue;
      const kept = [];
      for (let i = 0; i < n; i++) if (mask & (1 << i)) kept.push(nums[i]);
      result.push(kept);
    }
    return result;
  };
  const options1 = keepSets(nums1);
  const options2 = keepSets(nums2);
  let best = 0;
  for (const a of options1)
    for (const b of options2) best = Math.max(best, new Set([...a, ...b]).size);
  return best;
}

