function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const spread = [50, 1500, 3000, 1000000000][Math.floor(rand() * 4)];
    const shift = Math.floor(rand() * spread / 2);
    const pick = (offset) => Array.from({ length: n }, () => 1 + Math.floor(rand() * spread) + offset);
    return [pick(0), pick(shift).map(v => Math.min(v, 1000000000))];
  }
  const n = 2 * (1 + Math.floor(rand() * 4));
  const range = 1 + Math.floor(rand() * 7);
  const pick = () => Array.from({ length: n }, () => 1 + Math.floor(rand() * range));
  return [pick(), pick()];
}
